import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.gmyryY1Z.js";const u=JSON.parse('{"title":"Architecture Comparison","description":"","frontmatter":{},"headers":[],"relativePath":"en/evolution/comparison.md","filePath":"en/evolution/comparison.md","lastUpdated":null}'),n={name:"en/evolution/comparison.md"};function r(o,e,l,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture-comparison" tabindex="-1">Architecture Comparison <a class="header-anchor" href="#architecture-comparison" aria-label="Permalink to &quot;Architecture Comparison&quot;">​</a></h1><p>A multi-dimensional comparison between Polyrepo and Monorepo architectures.</p><h2 id="summary-table" tabindex="-1">Summary Table <a class="header-anchor" href="#summary-table" aria-label="Permalink to &quot;Summary Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Polyrepo</th><th>Monorepo</th></tr></thead><tbody><tr><td>Repo structure</td><td>Single repo, single app</td><td>Single repo, multiple packages &amp; apps</td></tr><tr><td>Version management</td><td>Single package.json</td><td>pnpm workspace catalog</td></tr><tr><td>Build tooling</td><td>Direct vite</td><td>turbo + vite</td></tr><tr><td>Code reuse</td><td>Manual copy</td><td>workspace package references</td></tr><tr><td>UI expansion</td><td>Fork or copy</td><td>Add new app/</td></tr><tr><td>Package boundaries</td><td>None (src/ mixed)</td><td>Clear (packages hierarchy)</td></tr><tr><td>Onboarding cost</td><td>Low</td><td>Medium (requires understanding turbo/pnpm workspace)</td></tr><tr><td>Long-term maintenance</td><td>High (grows with scale)</td><td>Low (shared infrastructure)</td></tr></tbody></table><h2 id="dependency-version-management" tabindex="-1">Dependency Version Management <a class="header-anchor" href="#dependency-version-management" aria-label="Permalink to &quot;Dependency Version Management&quot;">​</a></h2><p><strong>Polyrepo:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;vue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^3.4.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ant-design-vue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^4.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;element-plus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^2.6.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>All dependencies mixed in one file. Multiple projects risk version drift.</p><p><strong>Monorepo:</strong></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  vue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^3.5.17</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ant-design-vue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^4.2.6</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  element-plus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^2.10.2</span></span></code></pre></div><p>Centralized — upgrading affects all packages at once.</p><h2 id="supporting-multiple-ui-frameworks" tabindex="-1">Supporting Multiple UI Frameworks <a class="header-anchor" href="#supporting-multiple-ui-frameworks" aria-label="Permalink to &quot;Supporting Multiple UI Frameworks&quot;">​</a></h2><p><strong>Polyrepo:</strong> Each UI framework requires its own repository or project, with separate build configs and toolchains.</p><p><strong>Monorepo:</strong></p><ul><li>Create <code>apps/web-{name}/</code></li><li>Inherit <code>@fast-vue3/vite-config</code> (just pass in the UI resolver)</li><li>Reuse all <code>packages/*</code> shared infrastructure</li><li>Add a new UI framework in minutes</li></ul><h2 id="build-performance" tabindex="-1">Build Performance <a class="header-anchor" href="#build-performance" aria-label="Permalink to &quot;Build Performance&quot;">​</a></h2><p><strong>Polyrepo:</strong> Every build is a full rebuild — no incremental caching.</p><p><strong>Monorepo (Turbo):</strong></p><ul><li>Build result caching (local <code>.turbo/cache</code>)</li><li>Parallel builds across packages</li><li>Only rebuild affected packages (<code>turbo --filter</code>)</li></ul><h2 id="when-to-use-each" tabindex="-1">When to Use Each <a class="header-anchor" href="#when-to-use-each" aria-label="Permalink to &quot;When to Use Each&quot;">​</a></h2><h3 id="polyrepo-is-appropriate-for" tabindex="-1">Polyrepo is appropriate for <a class="header-anchor" href="#polyrepo-is-appropriate-for" aria-label="Permalink to &quot;Polyrepo is appropriate for&quot;">​</a></h3><ul><li>Single product with no multi-UI requirements</li><li>Small teams or personal projects</li><li>Rapid prototyping</li><li>No cross-project code reuse needed</li></ul><h3 id="monorepo-is-appropriate-for" tabindex="-1">Monorepo is appropriate for <a class="header-anchor" href="#monorepo-is-appropriate-for" aria-label="Permalink to &quot;Monorepo is appropriate for&quot;">​</a></h3><ul><li>Multiple UI frameworks or product lines</li><li>Large amounts of reusable infrastructure</li><li>Team collaboration requiring consistent standards</li><li>Long-term maintainability focus</li><li>Need for build caching and task parallelism</li></ul><h2 id="migration-cost" tabindex="-1">Migration Cost <a class="header-anchor" href="#migration-cost" aria-label="Permalink to &quot;Migration Cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Effort</th><th>One-time / Ongoing</th></tr></thead><tbody><tr><td>Learning pnpm workspace</td><td>Small</td><td>One-time</td></tr><tr><td>Turbo configuration</td><td>Small</td><td>One-time</td></tr><tr><td>Splitting packages</td><td>Medium</td><td>One-time</td></tr><tr><td>Migrating existing code</td><td>Medium-Large</td><td>One-time</td></tr><tr><td>Team learning curve</td><td>Small-Medium</td><td>One-time</td></tr></tbody></table><p>Post-migration: marginal cost of adding new UI apps or upgrading shared infrastructure approaches zero.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><blockquote><p>For a &quot;multi-UI ecosystem + shared infrastructure + long-term evolution&quot; scenario, Monorepo is the better choice.</p></blockquote><p>Fast Vue3&#39;s migration was not chasing new technology trends — it was a natural consequence of engineering scope and requirements:</p><ul><li>A single Polyrepo cannot elegantly support 5 UI ecosystems</li><li>Shared infrastructure in Polyrepo can only be maintained through manual copying</li><li>Monorepo makes &quot;version consistency + code reuse + engineering uniformity&quot; an architectural guarantee</li></ul>`,31)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
